// js/nyc-geodata.js — the engine's geography entry point, now an adapter over the Pardubice data
// (js/pardubice-geodata.js, generated by tools/build-pardubice.mjs). It keeps the GEO shape the engine reads: the
// Manhattan grid fields stay empty, so js/road-network.js builds every street from `roadGraph` (its non-grid step 4b),
// and `pardubice` carries the city's own data to the modules that draw it.
// Frame: 1 unit = 1 m, x = east, z = south, true north up, origin at Zelená brána.
import { PARDUBICE } from './pardubice-geodata.js';

const [minX, minZ, maxX, maxZ] = PARDUBICE.meta.bounds;
const boundsRing = [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ];
const FAR = 1e6; // Manhattan-only areas live far outside the map so their tests never match

export const GEO = {
  version: 1,
  city: 'Pardubice',
  frame: { bearingDeg: 0, origin: 'Zelená brána', units: 'm', cutZ: -Infinity, strip: 0, sidewalk: 3 },
  manhattan: boundsRing,
  upperManhattan: boundsRing,
  innerShore: boundsRing,
  islands: {},
  boroughs: {},
  streets: [],
  avenues: [],
  broadway: [],
  plazas: [],
  roads: [],
  roadGraph: PARDUBICE.roadGraph,
  blocks: [],
  parks: [],
  centralPark: { bounds: { minX: FAR, maxX: FAR + 1, minZ: FAR, maxZ: FAR + 1 }, outline: [], lawns: [], drives: [], water: [] },
  piers: [],
  bridges: {},
  landmarks: {},
  points: {},
  pardubice: PARDUBICE
};
